// @ts-nocheck
// Approved Colabb marketing composition. Static copy only; actions are handled by React.
const needs = [
  {id:'electrical',icon:'electrical',label:'Electrical work',title:'The roof is ready. Now for the electrical work.',body:'Find a company for wiring, inverter connections and commissioning.',service:'Electrical installation',photo:'detail',caption:'Specialist work. A clear scope.'},
  {id:'crew',icon:'crew',label:'Installation crews',title:'Your next phase needs the right crew.',body:'Find installation teams with the experience and coverage your job needs.',service:'Specialist electrical crews',photo:'roof',caption:'More hands. One shared plan.'},
  {id:'equipment',icon:'equipment',label:'Equipment sourcing',title:'A defined requirement. A better conversation.',body:'Describe the equipment, quantities and delivery needs in one brief.',service:'Equipment sourcing',photo:'planning',caption:'The details make the difference.'},
  {id:'testing',icon:'checklist',label:'Testing & handover',title:'The last checks deserve the right specialist.',body:'Find support for system checks, commissioning and a documented handover.',service:'Testing & commissioning',photo:'detail',caption:'From the work to the proof.'},
  {id:'maintenance',icon:'tools',label:'Service & maintenance',title:'Keep the next step clear.',body:'Explain the fault, site and system. Find a company with the right service experience.',service:'Service & maintenance',photo:'roof',caption:'Practical support for working systems.'}
];
const stages = [
  ['The brief','Post what you need.','Describe the scope, timing and location. Add plans, photos and questions for companies to answer.','document'],
  ['The company','Find companies for the job.','Review services, service areas and past projects. Invite suitable companies to send a proposal.','company'],
  ['The proposal','Compare proposals and choose.','Read the approach, documents and price together. Ask questions before choosing a company.','proposal'],
  ['The work','Review and approve the work.','Keep messages, files and progress with the job. Review the provider’s proof before approving each task.','proof']
];
export function marketingView({state:s,I,photo,companyLogo,publicCompanies=[],renderNetworkPreview=()=>''}: any) {
  const page=s.marketingPage||'home';
  const escape=(value:unknown)=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const actualCompanies=publicCompanies.filter(c=>c.is_demo===false);
  const profileUrl=c=>'/'+encodeURIComponent(c.username);
  const logoUrl=c=>/^\/(?:api\/company-assets\/|assets\/companies\/|brand\/companies\/)/.test(c.logo_url||'')?c.logo_url:'';
  const logo=c=>logoUrl(c)?`<img src="${escape(logoUrl(c))}" alt="" loading="lazy"/>`:'<span class="mx-company-empty-mark" aria-hidden="true"></span>';

  const a=(label,action,value='',primary=false,extra='')=>`<button class="mk-btn${primary?' mk-primary':''}" data-action="${action}" data-value="${value}" ${extra}>${label}</button>`;
  const link=(label,action,value='')=>`<button class="mk-link" data-action="${action}" data-value="${value}">${label}${I('arrow-right',18)}</button>`;
  const kicker=t=>`<p class="mk-kicker">${t}</p>`;
  const footnote='<p class="mk-example-note">Example workflow. Company names, prices and project images are illustrative.</p>';
  const photoBlock=(key,alt,cls='')=>`<div class="mk-photo ${cls}">${photo(key,alt)}</div>`;
  const actions=(work=false)=>`<div class="mk-actions">${a(work?'Set up your company':'Post a job','marketing-start',work?'company':'post-job',true)}${link(work?'Explore jobs':'Explore companies',work?'marketing-jobs':'marketing-companies')}</div>`;
  const brandLine=()=>`<h2 class="mk-brand-line"><span>Good work</span> <span class="mk-brand-line-bridge">happens in</span> <span>great company.</span></h2>`;
  const close=()=>`<section class="mk-close mk-wrap"><div>${kicker('YOUR NEXT WORKING CONNECTION')}${brandLine()}</div><div><p>Find the right company to work with.<br>Meet the people who make it happen.</p><div class="mk-actions">${a('Find a company','marketing-companies','',true)}${link('Find work','marketing-page','work')}</div></div></section>`;
  function walkthrough(standalone=false){
    const i=Number(s.marketingStage||0),st=stages[i];
    let artifact='';
    if(i===0)artifact=`<div class="mk-paper-label">${I('document',18)} JOB BRIEF <span>EXAMPLE</span></div><h3>Electrical work for a<br>250 kW rooftop system</h3><div class="mk-location">${I('location',16)} Cleveland, Ohio <span>Commercial rooftop</span></div><p class="mk-paper-body">DC and AC wiring, inverter connections, grounding and electrical checks. A documented handover is part of the scope.</p><div class="mk-file">${I('attachment',20)}<span><strong>Rooftop electrical plan.pdf</strong><small>Plans and requirements stay with the brief.</small></span></div><div class="mk-paper-end"><span>${I('calendar',16)} Start window agreed with provider</span>${link('Try posting a job','marketing-start','post-job')}</div>`;
    if(i===1)artifact=`<div class="mk-paper-label">${I('company',18)} COMPANY PROFILE <span>EXAMPLE</span></div><div class="mk-company">${companyLogo('summit')}<div><h3>Summit Grid Electric</h3><p>Cleveland, Ohio</p></div></div><p class="mk-paper-body">Commercial electrical work, commissioning and solar service.</p><ul class="mk-fit-list"><li>${I('electrical',18)} Electrical installation & testing</li><li>${I('location',18)} Northeast Ohio</li><li>${I('image',18)} Relevant project examples</li></ul><div class="mk-paper-end"><span>Review services, coverage and past projects.</span>${link('Browse companies','marketing-companies')}</div>`;
    if(i===2)artifact=`<div class="mk-paper-label">${I('proposal',18)} PROPOSAL <span>EXAMPLE</span></div><div class="mk-quote-top"><div><small>Summit Grid Electric</small><h3>Electrical installation and testing.</h3></div><div><small>Proposed total</small><strong>$38,400</strong></div></div><p class="mk-paper-body">“We’ll coordinate the electrical installation with your rooftop crew, complete the system checks and share the results at handover.”</p><div class="mk-proposal-facts"><span>${I('calendar',18)} 2 weeks to complete the work</span><span>${I('document',18)} Scope and supporting files</span></div><div class="mk-paper-end"><span>Confirm the scope, schedule and price.</span>${link('See how it works','marketing-page','how')}</div>`;
    if(i===3)artifact=`<div class="mk-paper-label">${I('proof',18)} SHARED CHECKLIST <span>EXAMPLE</span></div><h3>Review proof for each task.</h3><div class="mk-task">${I('approve',20)}<span>Installation photographs<strong>Approved by the hirer</strong></span></div><div class="mk-task">${I('document',20)}<span>Testing & handover<strong>Proof submitted · Needs review</strong></span><span class="mk-task-dot"></span></div><div class="mk-proof-file">${photo('detail','Illustrative electrical work detail')}<span><strong>Test results & site photographs</strong><small>Shared by the chosen provider.</small></span></div><div class="mk-paper-end"><span>The hiring company approves or requests changes.</span>${link('Understand the process','marketing-page','how')}</div>`;
    return `<section class="mk-flow ${standalone?'mk-flow-full':''}"><div class="mk-wrap"><div class="mk-section-top"><div>${kicker('FROM POSTING TO COMPLETION')}<h2>Post the job.<br>Approve the finished work.</h2></div><p>Each job keeps its proposals, messages, files and task approvals in one place.</p></div><div class="mk-flow-layout"><div class="mk-step-list" aria-label="Explore the job process">${stages.map(([label,title,body,icon],idx)=>`<button data-action="marketing-stage" data-value="${idx}" aria-pressed="${i===idx}" aria-controls="mk-artifact"><span class="mk-step-number">0${idx+1}</span><span><strong>${title}</strong>${i===idx?`<span class="mk-step-description">${body}</span>`:''}</span>${I('arrow-right',18)}</button>`).join('')}</div><div class="mk-artifact-wrap"><article id="mk-artifact" class="mk-artifact" aria-live="polite" aria-label="${st[0]} example">${artifact}</article>${footnote}</div></div></div></section>`;
  }
  function faq(){return `<section class="mk-wrap mk-faq"><div>${kicker('COMMON QUESTIONS')}<h2>Your questions,<br>answered.</h2></div><div>${[
    ['Can my company hire and find work?','Yes. Use the same company account to post jobs, send proposals and message other companies.'],
    ['Is every listed company on Colabb?','No. Companies with the “On Colabb” mark have a team using Colabb. Other profiles are public listings that the company has not yet claimed.'],
    ['What does “On Colabb” mean?','It means the company has an active team account here. The mark does not verify its qualifications. Check its services, past projects and credentials when choosing who to hire.'],
    ['Can I message a company without posting a job?','Yes. Open a profile with the “On Colabb” mark and select Message company. Your company owner or administrator sends the first request. Once accepted, both teams can reply and share images or PDFs. Find these conversations under Inbox → Companies.'],
    ['What happens if a company does not accept my request?','You cannot send more messages until the company accepts. It can decline the request, and you can withdraw it.'],
    ['Who can see company messages?','Members of the two participating companies can read the conversation. Company owners and administrators can accept requests or block further contact.'],
    ['What is Network?','Network is where companies share posts and join company-hosted communities. Follow company updates, ask questions and discuss subjects such as equipment sourcing or compliance. Private company messages stay in Inbox.'],
    ['Can my company create a community?','Yes. Your company can host a community, set its rules and manage membership. Hosts define the topics, post types and any extra fields members fill in when posting.'],
    ['Is a company profile separate from its posts?','No. Your company profile is also its page on Colabb. People can view your services and projects, follow the company and open its posts from the same profile.'],
    ['How is work marked complete?','Only the company chosen for the job can submit task proof. The hiring company reviews it, approves each task or requests changes, then reviews the final submission before closing the job.'],
    ['Does Colabb hold the payment?','No. Agree payment terms and pay the other company directly. Colabb keeps the proposal and work records, but does not hold or transfer your payment.']
  ].map(([q,ans])=>`<details><summary>${q}${I('chevron-down',18)}</summary><p>${ans}</p></details>`).join('')}</div></section>`;}
  const scopeExamples={
    electrical:{name:'Electrical',need:'An electrical team.',company:'cmco-electric',service:'Electrical & solar design-build',location:'Loomis, California',trade:'Electrical',icon:'electrical'},
    installation:{name:'Installation',need:'A solar installation team.',company:'yellowlite-inc',service:'Solar design and installation',location:'Cleveland, Ohio',trade:'Installation',icon:'solar-panel'},
    equipment:{name:'Equipment',need:'Equipment for the next job.',company:'sunhub-solar',service:'Equipment supply',location:'United States',trade:'Equipment',icon:'equipment'}
  };
  function sharedScope(){
    const key=s.marketingScope||'electrical',ex=scopeExamples[key]||scopeExamples.electrical;
    const company=actualCompanies.find(c=>c.username===ex.company);
    if(!company)return '';
    const service=company.services.includes(ex.service)?ex.service:company.services[0]||company.type;
    return `<section class="mx-common mx-fit mk-wrap" id="shared-scope"><div class="mx-section-intro">${kicker('FIND COMPANIES BY WHAT THEY DO')}<div><h2>The missing piece<br>might be another company.</h2><p>Browse by service and location to find companies for your job.</p></div></div>
      <div class="mx-scope-choices" aria-label="Choose the work you need">${Object.entries(scopeExamples).filter(([,x])=>actualCompanies.some(c=>c.username===x.company)).map(([id,x])=>`<button data-action="marketing-scope" data-value="${id}" aria-pressed="${key===id}" aria-controls="mx-fit-example">${I(x.icon,20)} ${x.name}</button>`).join('')}</div>
      <div class="mx-fit-example" id="mx-fit-example" aria-live="polite" aria-atomic="true">
        <article class="mx-fit-need"><span class="mx-fit-label">YOU NEED</span><h3>${ex.need}</h3><p>${I('location',18)}${ex.location}</p><span class="mx-fit-bridge" aria-hidden="true">${I('arrow-right',26)}</span></article>
        <article class="mx-fit-company"><span class="mx-fit-label">THEY DO</span><h3>${escape(service)}</h3><div class="mx-fit-provider">${logo(company)}<div><strong>${escape(company.name)}</strong><span>${I('location',15)}Based in ${escape(company.location)}</span></div></div><a class="mx-fit-profile" href="${profileUrl(company)}" aria-label="View ${escape(company.name)} profile">${I('arrow-right',21)}</a></article>
      </div>
      <div class="mx-fit-bottom"><p><strong>Check services and coverage before you hire.</strong><span>Review the profile, then confirm the company can take on your work.</span></p><a class="mk-btn" href="/providers?trade=${encodeURIComponent(ex.trade)}&amp;sample=false">Find companies for this work ${I('arrow-right',18)}</a></div><p class="mx-fit-caption">This is a real company. Services are taken from its Colabb profile.</p>
    </section>`;
  }
  function companyMessaging(){return `<section class="mx-messaging mk-wrap" aria-labelledby="mx-messaging-title">
    <div class="mx-messaging-copy">${kicker('COMPANY MESSAGING')}<h2 id="mx-messaging-title">Start with<br>a conversation.</h2><p>Ask about services, equipment or availability before you post a job. Send a message request directly from a company’s profile.</p>
      <ol class="mx-message-steps"><li><span>01</span><div><h3>Find a company on Colabb.</h3><p>Look for the “On Colabb” mark, then select <strong>Message company</strong> on its profile.</p></div></li><li><span>02</span><div><h3>Send an introduction.</h3><p>Your company owner or administrator sends the first request. The other company decides whether to accept.</p></div></li><li><span>03</span><div><h3>Keep both teams in the conversation.</h3><p>Once accepted, team members can reply and share images or PDFs in <strong>Inbox → Companies</strong>.</p></div></li></ol>
      <a class="mk-btn mk-primary" href="/providers">Find a company to message ${I('arrow-right',18)}</a>
    </div>
    <div class="mx-message-example"><div class="mx-message-example-heading"><span>${I('message',19)} COMPANY CONVERSATION</span><small>EXAMPLE</small></div><div class="mx-message-thread"><div class="mx-message-sample"><span>Your company · Message request</span><p>Hi, do you handle electrical work on commercial rooftops in Ohio? We’re planning a 250 kW installation.</p></div><div class="mx-message-accepted">${I('completed',16)} The company accepts your request.</div><div class="mx-message-sample mx-message-reply"><span>Their team</span><p>Yes, we cover that area. Send us the plans and your preferred start date.</p></div><div class="mx-message-sample-file">${I('document',22)}<span><strong>Rooftop plans.pdf</strong><small>Files can be shared after acceptance.</small></span></div></div><div class="mx-message-example-footer">${I('crew',18)} A shared conversation for both companies’ teams.</div></div>
  </section>`;}
  function networkIntro(standalone=false){
    const community=s.marketingNetwork==='communities';
    return `<section class="mx-network-intro mk-wrap${standalone?' mx-network-hero':''}" aria-labelledby="mx-network-title"><div class="mx-network-heading">${kicker('NETWORK / COMPANIES & COMMUNITIES')}${standalone?'<h1 id="mx-network-title">Follow companies.<br>Join the conversation.</h1>':'<h2 id="mx-network-title">Stay connected.<br>Between jobs, too.</h2>'}<p>See what other solar companies are working on. Share your own posts and join communities to ask questions, source equipment and exchange practical advice.</p></div><div class="mx-network-layout"><div class="mx-network-explainer"><div class="mx-network-switch" role="group" aria-label="Explore Network features"><button data-action="marketing-network" data-value="feed" aria-pressed="${!community}" aria-controls="mx-network-example">${I('image',18)} Company posts</button><button data-action="marketing-network" data-value="communities" aria-pressed="${community}" aria-controls="mx-network-example">${I('crew',18)} Communities</button></div><div class="mx-network-feature" aria-live="polite"><span class="mx-network-number">${community?'02':'01'} / NETWORK</span><h3>${community?'Talk with people who know the work.':'Follow the companies you want to hear from.'}</h3><p>${community?'Join a company-hosted community around a specific subject. Start a discussion, reply to a question or share a requirement with the details people need to help.':'Follow a company to see its posts in your feed. Share project photos and news from your own company, react to posts, leave comments and save useful posts for later.'}</p><ul>${(community?['Find discussions by topic.','Mention people in posts and comments.','Keep the replies with the post they belong to.']:['Publish from your company’s existing profile.','Keep captions and attachments together.','Open a post to read and join its comments.']).map(x=>`<li>${I('completed',17)}${x}</li>`).join('')}</ul></div>${standalone?a('Sign in to Network '+I('arrow-right',18),'marketing-signin','/network',true):link('Explore Network','marketing-page','network')}</div><div class="mx-network-demo" id="mx-network-example" data-network-preview="${community?'communities':'feed'}">${renderNetworkPreview(community?'communities':'feed')}</div></div></section>`;
  }
  function networkPage(){return `${networkIntro(true)}<section class="mx-network-host mk-wrap" aria-labelledby="mx-network-host-title"><div class="mx-network-host-copy">${kicker('COMMUNITIES, HOSTED BY COMPANIES')}<h2 id="mx-network-host-title">Create a useful place<br>for your industry.</h2><p>Your company can create and manage a community for equipment sourcing, fieldwork, compliance, customer support or another subject your members care about.</p><a class="mk-link" href="/network/communities">Discover communities ${I('arrow-right',18)}</a></div><div class="mx-host-features"><article>${I('settings',23)}<div><h3>Set the topics and post types.</h3><p>Organize discussions by topic. Add post types such as “Looking for equipment” or “Technical question” to suit your community.</p></div></article><article>${I('document',23)}<div><h3>Ask for the details you need.</h3><p>Add topic-specific fields for quantities, dates, text or a choice of options. Make a field required when a post needs that information.</p></div></article><article>${I('lock',23)}<div><h3>Choose who can join and read.</h3><p>Public discussions are readable by people on Colabb. Private discussions and files are for approved members. Hosts manage rules, membership and moderation.</p></div></article></div></section><section class="mx-network-context mk-wrap"><div>${kicker('WHERE EACH CONVERSATION BELONGS')}<h2>Share with the network.<br>Talk privately in Inbox.</h2></div><div class="mx-conversation-types"><article><span>01</span><h3>Company posts</h3><p>Share your company’s news, project photos and updates. People can follow your company and comment on its posts.</p></article><article><span>02</span><h3>Community discussions</h3><p>Ask questions and share information on a particular subject. Replies stay with each discussion.</p></article><article><span>03</span><h3>Private conversations</h3><p>Send a company a message request. Once accepted, both teams can talk and share files in Inbox.</p></article></div></section>${companyMessaging()}${faq()}${editorialClose()}`;}
  function editorialClose(){return `<section class="mx-close mk-wrap"><div class="mx-close-top">${kicker('HIRE A COMPANY OR FIND YOUR NEXT JOB')}<span>The working network for solar.</span></div>${brandLine()}<div class="mx-close-actions"><p>Find the right company to work with.<br>Meet the people who make it happen.</p><div class="mk-actions">${a('Find a company','marketing-companies','',true)}${link('Find work','marketing-page','work')}</div></div></section>`;}
  function ribbon(){const items=[['plan','planning','Describe the job.','Tell companies what needs doing.','hire'],['build','roof','Find the right company.','Compare services and experience.','companies'],['check','craft','Review the finished work.','Approve each task after reviewing the proof.','how']];return `<section class="mx-ribbon-wrap" aria-label="Different contributions to the same work"><div class="mx-ribbon" data-selected="${s.marketingRibbon||''}">${items.map(([id,img,title,sub,target],i)=>`<button class="mx-ribbon-segment mx-ribbon-${i}" data-action="marketing-ribbon" data-value="${id}" aria-pressed="${s.marketingRibbon===id}" aria-label="${title} Explore this contribution"><span class="mx-ribbon-image">${photo(img,'Illustrative '+(id==='plan'?'planning with technical drawings':id==='build'?'commercial solar installation':'inspection and handover work'))}</span><span class="mx-ribbon-caption"><span>0${i+1}</span><strong>${title}</strong>${I('arrow-right',16)}</span></button>`).join('')}</div>${s.marketingRibbon?`<div class="mx-ribbon-detail mk-wrap" aria-live="polite"><span>${items.find(x=>x[0]===s.marketingRibbon)[3]}</span><p>${({plan:'Put the scope, drawings and questions in one clear brief.',build:'Explore companies by their services, experience and coverage.',check:'Ask for evidence. Review the work before calling it done.'})[s.marketingRibbon]}</p>${link(({plan:'See how to hire',build:'Explore companies',check:'Explore the process'})[s.marketingRibbon],s.marketingRibbon==='build'?'marketing-companies':'marketing-page',s.marketingRibbon==='plan'?'hire':'how')}</div>`:''}</section>`;}
  function home(){return `<section class="mx-hero mk-wrap">${kicker('COLABB / THE WORKING NETWORK FOR SOLAR')}<div class="mx-headline"><div class="mx-hero-display"><h1><span>No one builds</span><span><span class="mk-orange">solar</span> alone<span class="mk-orange">.</span></span></h1><div class="mx-hero-actions"><a class="mk-btn mk-primary mx-hero-post" href="/jobs/new"><span>Post a job</span>${I('post-job',24)}</a></div></div><p>Find solar crews, specialists and suppliers. Post jobs, follow company posts and exchange advice in communities.</p></div></section>${ribbon()}${sharedScope()}
    <section class="mx-real-network"><div class="mk-wrap"><div class="mx-section-intro">${kicker('EXPLORE THE COMPANIES')}<div><h2>Find installers,<br>specialists and suppliers.</h2><p>Review services and past work. Look for the “On Colabb” mark to find companies you can message here.</p></div></div><div class="mx-real-list">${actualCompanies.filter(c=>['sunhub-solar','yellowlite-inc'].includes(c.username)).map(c=>`<article class="mx-real-company"><div class="mx-real-identity"><span class="mx-real-mark">${logo(c)}</span><div><span class="mx-real-kind">${escape(c.type)}</span><h3>${escape(c.name)}</h3><p>${I('location',15)}${escape(c.location)}</p></div></div><div class="mx-real-services"><span class="mx-real-label">WHAT THEY DO</span><ul>${c.services.slice(0,3).map(service=>`<li>${escape(service)}</li>`).join('')}</ul></div><div class="mx-real-action"><span class="mx-real-membership">${I('company',15)}${c.on_colabb?'Company-managed profile':'Public company profile'}</span><a class="mk-btn" href="${profileUrl(c)}" aria-label="View ${escape(c.name)} profile on Colabb">View profile ${I('arrow-right',18)}</a></div></article>`).join('')}</div><div class="mx-real-bottom">${link('Explore all companies','marketing-companies')}<p>Explore real company profiles and the services they offer.</p></div></div></section>
    ${networkIntro()}${companyMessaging()}<section class="mx-manifesto"><div class="mk-wrap"><span class="mk-kicker">MANAGE THE JOB TOGETHER</span><div class="mx-manifesto-lines"><span>Choose a company.</span><span>Track each task.</span><span>Approve the work.</span></div><div class="mx-manifesto-bottom"><p>Keep proposals, messages and files with the job. The chosen company submits proof for each task. You approve it or request changes.</p>${link('See how Colabb works','marketing-page','how')}</div></div></section>
    <section class="mx-origin-preview mk-wrap" aria-labelledby="mx-origin-title">
      <div class="mx-origin-heading">${kicker('FROM THE ROOF UP.')}${link('Our story','marketing-page','story')}</div>
      <div class="mx-origin-scene">
        <figure class="mx-origin-photo">${photo('roof','Illustrative rooftop solar installation; not an archival company photograph')}<figcaption>Illustrative solar installation.</figcaption></figure>
        <div class="mx-origin-note"><span class="mx-origin-eyebrow">BUILT FROM INSTALLATION EXPERIENCE</span><h2 id="mx-origin-title">Our roots are<br>in installation.</h2><p>Sunhub’s ownership team first founded YellowLite, a solar installer. Sunhub is building a supply chain ecosystem for solar. Colabb, a Sunhub company, helps solar businesses work together.</p></div>
      </div>
      <ol class="mx-origin-lineage" aria-label="Our installation roots, parent company and working network">
        <li><span class="mx-origin-relationship">The team’s roots</span><div class="mx-origin-brand"><span class="mx-origin-symbol mx-origin-yellowlite"><img src="/brand/companies/yellowlite.webp" alt="" loading="lazy"/></span><strong>YellowLite</strong></div><span class="mx-origin-role">Solar installation</span><span class="mx-origin-connector" aria-hidden="true">${I('arrow-right',24)}</span></li>
        <li><span class="mx-origin-relationship">Our parent company</span><div class="mx-origin-brand"><span class="mx-origin-symbol"><img src="/brand/companies/sunhub.png" alt="" loading="lazy"/></span><strong>Sunhub</strong></div><span class="mx-origin-role">Supply chain ecosystem</span><span class="mx-origin-connector" aria-hidden="true">${I('arrow-right',24)}</span></li>
        <li><span class="mx-origin-relationship">A Sunhub company</span><div class="mx-origin-brand mx-origin-colabb"><img src="/brand/marks/lockup-primary.svg" alt="Colabb" loading="lazy"/></div><span class="mx-origin-role">Working network</span></li>
      </ol>
    </section>${editorialClose()}`;}
  function audience(work){return `<section class="mx-audience-title mk-wrap">${kicker(work?'FOR COMPANIES LOOKING FOR WORK':'FOR COMPANIES HIRING HELP')}<h1>${work?'Show what you do.<br><span>Find your next job.</span>':'Find the company<br><span>your job needs.</span>'}</h1><div class="mx-audience-intro"><p>${work?'Show your services and past projects. Send proposals for relevant jobs, share company posts and receive message requests from potential clients.':'Post what you need, from installation crews to equipment sourcing. Compare company matches and proposals, ask questions in communities or message a company directly.'}</p>${actions(work)}</div></section><section class="mx-audience-spread mk-wrap"><div class="mx-audience-photo">${photo(work?'craft':'planning',work?'Illustrative specialist electrical inspection':'Illustrative solar project planning')}</div><article class="mx-audience-note"><span class="mx-page-number">${work?'02':'01'} / COLABB</span><h2>${work?'Help hirers see<br>what you can do.':'Give companies<br>a clear job brief.'}</h2><p>${work?'Add project photos and describe the work your team completed, so hirers can judge your experience.':'Describe the work, location and timing so companies can decide whether to send a proposal.'}</p><span class="mx-note-rule"></span><p>${work?'List your services and the areas you cover. Keep your availability up to date.':'Attach plans and photos, and add questions you want every company to answer.'}</p></article></section>
    <section class="mx-principles mk-wrap"><div>${kicker(work?'BUILD YOUR COMPANY PROFILE':'GET PROPOSALS YOU CAN COMPARE')}<h2>${work?'Make your services<br>easy to understand.':'Tell companies<br>what you need.'}</h2></div><div>${(work?[
      ['01','List the services you offer.','Add the services you offer, project types and the areas you cover.'],['02','Show relevant experience.','Share relevant project examples, credentials and reviews from completed Colabb jobs.'],['03','Explain how you would do the job.','Explain how you would deliver. Attach supporting documents, answer the questions, then set out your timing and price.']
    ]:[['01','Describe the work and the outcome.','Describe the outcome, location and timing. Add the tasks you will need to approve.'],['02','Add files and proposal questions.','Include plans and photos. Ask the questions you want answered in every proposal.'],['03','Compare proposals before choosing.','Compare the approach and supporting experience. Talk through availability and the details before agreeing.']]).map(([n,h,p])=>`<article><span>${n}</span><div><h3>${h}</h3><p>${p}</p></div></article>`).join('')}</div></section>
    ${networkIntro()}${companyMessaging()}${work?`<section class="mx-work-invitation mk-wrap"><div>${kicker('CLAIM YOUR COMPANY PROFILE')}<h2>Your company may<br>already be listed.</h2><p>Search for your company and request ownership of its profile. Once approved, you can edit its details, receive message requests and invite your team.</p>${a('Find your company '+I('arrow-right',18),'marketing-start','claim',true)}</div><div class="mx-profile-outline"><div>${companyLogo('summit')}<span>YOUR COMPANY</span></div><span class="mx-outline-line mx-outline-long"></span><span class="mx-outline-line"></span><div class="mx-outline-row">${I('electrical',24)} Services ${I('location',24)} Service area</div><div class="mx-outline-work">${photo('roof','Illustrative project example')}<span>Show projects<br>your team completed.</span></div></div></section>`:sharedScope()}
    <section class="mx-plain-statement mk-wrap"><span class="mk-kicker">${work?'YOUR NEXT JOB':'AFTER YOU CHOOSE'}</span><h2>${work?'Find a job that<br>needs your services.':'Review progress<br>and approve the work.'}</h2><p>${work?'Read the requirements, answer the hiring company’s questions and explain your approach. Include supporting files, your schedule and your price.':'The chosen company shares progress and proof. You review the work, request changes when needed and approve the outcome.'}</p>${link(work?'Explore jobs':'See how jobs work',work?'marketing-jobs':'marketing-page',work?'':'how')}</section>${editorialClose()}`;}
  function story(){const chapter=s.marketingChapter||'installation',chapters={installation:{no:'01',label:'YellowLite',heading:'It began with installation.',photo:'planning',year:'INSTALLATION ROOTS',body:'Sunhub’s ownership team founded YellowLite in Cleveland in 2009. Installing solar revealed the challenges of sourcing equipment, managing suppliers, finding stock and getting it to site.',question:'What does the industry need around the work?'},equipment:{no:'02',label:'Sunhub',heading:'A connected supply chain.',photo:'roof',year:'OUR PARENT COMPANY',body:'Sunhub is building the supply chain ecosystem for solar, connecting sourcing, selling, transactions and logistics. Its Marketplace, Sales Portal, Source Center, Fulfillment and Marketing bring that work together.',question:'How can the whole supply chain work better together?'},together:{no:'03',label:'Colabb',heading:'Colabb connects solar companies.',photo:'craft',year:'A SUNHUB COMPANY',body:'Colabb is a Sunhub company. Solar businesses use it to find work, hire other companies, exchange messages and share experience in communities. Job conversations, files and task approvals stay together.',question:'Who can help you get the work done?'}},ch=chapters[chapter]||chapters.installation;return `<section class="mx-story-title mk-wrap">${kicker('COLABB / A SUNHUB COMPANY')}<h1>From the roof.<br><span>To the companies<br>around it.</span></h1><p>Our parent company, Sunhub, is building a supply chain ecosystem for solar.<br>Colabb connects the companies doing the work.</p></section><section class="mx-fieldbook mk-wrap"><nav aria-label="Our story chapters">${Object.entries(chapters).map(([key,x])=>`<button data-action="marketing-chapter" data-value="${key}" aria-pressed="${chapter===key}"><span>${x.no}</span>${x.label}${I('arrow-right',17)}</button>`).join('')}</nav><div class="mx-fieldbook-spread" aria-live="polite"><div class="mx-fieldbook-image">${photo(ch.photo,'Illustrative solar work, not an archival photograph')}</div><article><div class="mx-fieldbook-meta"><span>FIELD NOTES / ${ch.no}</span><span>${ch.year}</span></div><h2>${ch.heading}</h2><p>${ch.body}</p><blockquote>${ch.question}</blockquote><span class="mx-fieldbook-foot">Built from the team’s experience in solar.</span></article></div><div class="mx-fieldbook-source"><span>Illustrative photography · The questions express Colabb’s perspective.</span><a href="https://business.sunhub.com/story" target="_blank" rel="noopener noreferrer">Read Sunhub’s published history ${I('arrow-right',16)}</a></div></section><section class="mx-beliefs mk-wrap">${kicker('WHAT WE BELIEVE')}<div><h2>Make the work clear.<br>Keep the people connected.</h2><p>Good relationships have practical foundations: a clear requirement, relevant experience and a shared understanding of what happens next.</p></div><div class="mx-beliefs-points"><article><span>01</span><h3>Say what you need.</h3><p>A specific brief gives another company something useful to respond to.</p></article><article><span>02</span><h3>Show the work you have done.</h3><p>Describe your services and show examples of projects your team completed.</p></article><article><span>03</span><h3>Approve each task after reviewing the proof.</h3><p>Share progress and proof for each task so the hiring company can review and approve it.</p></article></div></section>${editorialClose()}`;}
  return `<div class="mk-site">${page==='home'?home():page==='hire'?audience(false):page==='work'?audience(true):page==='story'?story():page==='network'?networkPage():`<section class="mk-wrap mk-how-title">${kicker('HOW COLABB WORKS')}<h1>From posting a job<br>to approving the work.</h1><p>Post your requirements, compare proposals and choose a company. Track tasks and review proof as work is completed. Between jobs, use Network to follow companies and take part in community discussions.</p></section>${walkthrough(true)}${companyMessaging()}${networkIntro()}${faq()}${editorialClose()}`}</div>`;
}
